edit('CompositionEngine.swift', '        metrics.rendered += 1\n        metrics.lastPresentationSeconds', '        let fanoutStarted = CompositionHotPathProfile.stamp()\n        defer { CompositionHotPathProfile.shared.record("fanout", since: fanoutStarted, sequence: frameSequence) }\n        metrics.rendered += 1\n        metrics.lastPresentationSeconds')
