# Replace the exact existing mailbox methods in the generated copy only. CPU stamps
# are captured under the existing lock, but event construction/storage is after unlock.
edit('CompositionEngine.swift', '    func post(_ frame: CompositedFrame) {\n        os_unfair_lock_lock(&lock)\n        if pending.count >= capacity {\n            drops += 1\n            pending.removeFirst()   // drop-oldest\n        }\n        pending.append(frame)\n        let shouldSchedule = !isDraining\n        if shouldSchedule { isDraining = true }\n        os_unfair_lock_unlock(&lock)\n        if shouldSchedule {\n            queue.async { self.drain() }\n        }\n    }', '    func post(_ frame: CompositedFrame) {\n        let postStarted = CompositionHotPathProfile.stamp()\n        os_unfair_lock_lock(&lock)\n        let acquired = CompositionHotPathProfile.stamp()\n        var dropStart: CompositionHotPathProfile.Stamp?\n        var dropEnd: CompositionHotPathProfile.Stamp?\n        if pending.count >= capacity {\n            drops += 1\n            dropStart = CompositionHotPathProfile.stamp()\n            pending.removeFirst()   // drop-oldest; same release location under lock\n            dropEnd = CompositionHotPathProfile.stamp()\n        }\n        pending.append(frame)\n        let shouldSchedule = !isDraining\n        if shouldSchedule { isDraining = true }\n        let heldEnd = CompositionHotPathProfile.stamp()\n        os_unfair_lock_unlock(&lock)\n        let unlocked = CompositionHotPathProfile.stamp()\n        if shouldSchedule {\n            queue.async { self.drain() }\n        }\n        let scheduleEnd = CompositionHotPathProfile.stamp()\n        let p = CompositionHotPathProfile.shared\n        p.record("mailboxLockWait." + profileName, since: postStarted, until: acquired, sequence: frame.sequence)\n        p.record("mailboxLockHeld." + profileName, since: acquired, until: heldEnd, sequence: frame.sequence)\n        if let dropStart, let dropEnd {\n            p.record("mailboxDropRemovalRelease." + profileName, since: dropStart, until: dropEnd, sequence: frame.sequence)\n        }\n        p.record("mailboxSchedule." + profileName, since: unlocked, until: scheduleEnd, sequence: frame.sequence)\n        p.record("mailboxPost." + profileName, since: postStarted, until: scheduleEnd, sequence: frame.sequence)\n    }')
edit('CompositionEngine.swift', '    private func drain() {\n        while true {\n            os_unfair_lock_lock(&lock)\n            guard !pending.isEmpty else {\n                isDraining = false\n                os_unfair_lock_unlock(&lock)\n                return\n            }\n            let frame = pending.removeFirst()\n            os_unfair_lock_unlock(&lock)\n            sink(frame)\n        }\n    }', '    private func drain() {\n        var priorCallbackEnd: CompositionHotPathProfile.Stamp?\n        while true {\n            let dequeueStarted = CompositionHotPathProfile.stamp()\n            if let priorCallbackEnd {\n                CompositionHotPathProfile.shared.record("mailboxBetweenCallbackResidual." + profileName, since: priorCallbackEnd, until: dequeueStarted)\n            }\n            os_unfair_lock_lock(&lock)\n            guard !pending.isEmpty else {\n                isDraining = false\n                os_unfair_lock_unlock(&lock)\n                return\n            }\n            let frame = pending.removeFirst()\n            os_unfair_lock_unlock(&lock)\n            let callbackStarted = CompositionHotPathProfile.stamp()\n            CompositionHotPathProfile.shared.record("mailboxDequeue." + profileName, since: dequeueStarted, until: callbackStarted, sequence: frame.sequence)\n            CompositionHotPathProfile.shared.point("mailboxDelivery." + profileName, sequence: frame.sequence)\n            let sinkStarted = CompositionHotPathProfile.stamp()\n            sink(frame)\n            let sinkEnded = CompositionHotPathProfile.stamp()\n            CompositionHotPathProfile.shared.record("mailboxSink." + profileName, since: sinkStarted, until: sinkEnded, sequence: frame.sequence)\n            priorCallbackEnd = CompositionHotPathProfile.stamp()\n        }\n    }')
